import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_c = sum(1 for x in opp if x == 'C')
    opp_d = n - opp_c
    last_me, last_opp = history[-1]

    # Endgame: defect against anyone who has ever defected.
    if n >= 98:
        if opp_d > 0:
            return 'D'
        return 'C'

    # Short opening: cooperate, but respond to an immediate defection.
    if n < 4:
        if n == 1:
            return 'C'
        if last_opp == 'D':
            return 'D' if opp_d >= 2 else 'C'
        return 'C'

    # Pure always-cooperator: exploit, but keep a small cooperative seed
    # alive to rebuild if the opponent turns out to be conditional.
    if opp_d == 0:
        # Defect often in the middle, but cooperate occasionally and near the
        # end (except final two rounds) to lock in mutual cooperation.
        if n >= 96:
            return 'C'
        if n % 7 == 0:
            return 'C'
        return 'D'

    # Pure always-defector: minimize losses with D.
    if opp_c == 0:
        return 'D'

    # Attack/repair pattern: if opponent defected on the last round after we
    # cooperated, punish once with D, then offer C to restore cooperation.
    if last_opp == 'D' and last_me == 'C':
        return 'D'

    # If we defected last and opponent defected, keep punishing only briefly.
    if last_opp == 'D' and last_me == 'D':
        # Count our current run of D
        my_d_run = 0
        for a in reversed(me):
            if a == 'D':
                my_d_run += 1
            else:
                break
        # After two D's in a row, probe cooperation once.
        if my_d_run >= 2:
            if opp_c >= 2 and rng.random() < 0.6:
                return 'C'
            return 'D'
        return 'D'

    # Opponent cooperated last round.
    if last_opp == 'C':
        # Detect a strong conditional / forgiving partner: keep cooperating.
        recent = opp[-10:]
        rec_c = sum(1 for x in recent if x == 'C')
        # Opponent mostly cooperative recently: reciprocate with C.
        if rec_c >= len(recent) - 2:
            # Occasionally test the waters if we've been too nice and the
            # opponent has some defection history, but be conservative.
            if opp_d >= 3 and n >= 30 and rng.random() < 0.05:
                return 'D'
            return 'C'
        # Opponent mixed: cooperate to encourage cooperation.
        if opp_c * 100 >= n * 45:
            return 'C'
        return 'D'

    return 'C'
